"""Index supplied SearchQA document boundaries; offsets are Unicode character offsets."""
import re

_STOP = set("a an the of in on at to for from and or by with is was are were be been this that these those it its as who what which when where how his her their has have had not one named called".split())


def _tokens(value):
    return {word.casefold() for word in re.findall(r"[^\W_]+", value) if len(word) > 1 and word.casefold() not in _STOP}


def _documents(text):
    starts = [match.start() for match in re.finditer(r"\[DOC\]", text)]
    if not starts:
        starts = [0]
    elif text[:starts[0]].strip():
        starts.insert(0, 0)
    records = []
    for number, start in enumerate(starts):
        end = starts[number + 1] if number + 1 < len(starts) else len(text)
        raw = text[start:end]
        title_marker, paragraph_marker = raw.find("[TLE]"), raw.find("[PAR]")
        title_start = start + title_marker + 5 if title_marker >= 0 else start
        title_end = start + paragraph_marker if paragraph_marker >= 0 else end
        if title_marker < 0 or title_end < title_start:
            title_start = title_end = start
        while title_start < title_end and text[title_start].isspace():
            title_start += 1
        while title_end > title_start and text[title_end - 1].isspace():
            title_end -= 1
        body_start = start + paragraph_marker + 5 if paragraph_marker >= 0 else start
        while body_start < end and text[body_start].isspace():
            body_start += 1
        records.append({"doc_id": number, "start": start, "end": end,
                        "title_start": title_start, "title_end": title_end, "body_start": body_start})
    return records


def run(ctx, inputs):
    question, context = inputs.get("question"), inputs.get("context")
    if not isinstance(question, str) or not isinstance(context, str):
        return {"status": "needs_input", "outputs": {}, "error": "question and context must be strings"}
    documents, clue = _documents(context), _tokens(question)
    seen, result = {}, []
    for doc in documents:
        raw = context[doc["start"]:doc["end"]]
        key = " ".join(raw.casefold().split())
        duplicate = seen.get(key)
        seen.setdefault(key, doc["doc_id"])
        preview_end = min(doc["end"], doc["body_start"] + 160)
        result.append({"doc_id": doc["doc_id"], "span": [doc["start"], doc["end"]],
                       "title": context[doc["title_start"]:doc["title_end"]],
                       "title_span": [doc["title_start"], doc["title_end"]],
                       "preview": context[doc["body_start"]:preview_end],
                       "preview_span": [doc["body_start"], preview_end],
                       "clue_terms_present": sorted(clue & _tokens(raw))[:32],
                       "duplicate_of": duplicate})
    report = {"context_chars": len(context), "document_count": len(documents), "documents": result[:64],
              "omitted_documents": max(0, len(result) - 64), "offset_unit": "unicode_character_end_exclusive",
              "meaning": "Source locations and literal clue overlap only; not semantic relevance or independent corroboration."}
    return {"status": "ok", "outputs": {"context_index": report}}

"""Return exact bounded source windows and conservatively detected explicit QA fields.

Lexical ranking is navigation, not an answer selector. No network, labels or lookup table.
"""
import math
import re

_STOP = set("a an the of in on at to for from and or by with is was are were be been this that these those it its as who what which when where how his her their has have had not one named called".split())


def _tokens(value):
    return {word.casefold() for word in re.findall(r"[^\W_]+", value) if len(word) > 1 and word.casefold() not in _STOP}


def _norm(value):
    return " ".join(re.findall(r"[^\W_]+", value.casefold()))


def _documents(text):
    starts = [match.start() for match in re.finditer(r"\[DOC\]", text)]
    if not starts:
        starts = [0]
    elif text[:starts[0]].strip():
        starts.insert(0, 0)
    records = []
    for number, start in enumerate(starts):
        end = starts[number + 1] if number + 1 < len(starts) else len(text)
        raw = text[start:end]
        title_marker, paragraph_marker = raw.find("[TLE]"), raw.find("[PAR]")
        title_start = start + title_marker + 5 if title_marker >= 0 else start
        title_end = start + paragraph_marker if paragraph_marker >= 0 else end
        if title_marker < 0 or title_end < title_start:
            title_start = title_end = start
        while title_start < title_end and text[title_start].isspace():
            title_start += 1
        while title_end > title_start and text[title_end - 1].isspace():
            title_end -= 1
        body_start = start + paragraph_marker + 5 if paragraph_marker >= 0 else start
        while body_start < end and text[body_start].isspace():
            body_start += 1
        records.append({"doc_id": number, "start": start, "end": end,
                        "title_start": title_start, "title_end": title_end, "body_start": body_start})
    return records


def _explicit_fields(text, question, documents):
    fields, target = [], _norm(question)
    if not target:
        return fields
    labelled = re.compile(r"(?:^|\n)[ \t]*(?:Q(?:uestion)?|Clue)[ \t]*:[ \t]*(?P<q>[^\n]+?)"
                          r"(?:[ \t]+|\n[ \t]*)(?:A(?:nswer)?)[ \t]*:[ \t]*(?P<a>[^\n]+)", re.I)
    for doc in documents:
        body = text[doc["body_start"]:doc["end"]]
        matches = []
        for match in labelled.finditer(body):
            matches.append((match.group("q"), match.span("q"), match.group("a"), match.span("a"), "explicit_Q_A_labels"))
        cursor = 0
        for line in body.splitlines(keepends=True):
            cells = list(re.finditer(r"[^|\t\r\n]+", line))
            if "|" in line or "\t" in line:
                for left, right in zip(cells, cells[1:]):
                    matches.append((left.group(), (cursor + left.start(), cursor + left.end()),
                                    right.group(), (cursor + right.start(), cursor + right.end()), "explicit_pipe_or_tab_fields"))
            cursor += len(line)
        for clue, clue_span, answer, answer_span, form in matches:
            if _norm(clue) != target or not answer.strip() or len(answer.strip()) > 256:
                continue
            left = len(answer) - len(answer.lstrip())
            right = len(answer.rstrip())
            start, end = doc["body_start"] + answer_span[0] + left, doc["body_start"] + answer_span[0] + right
            if any(field["answer_span"] == [start, end] for field in fields):
                continue
            fields.append({"doc_id": doc["doc_id"], "candidate": text[start:end], "answer_span": [start, end],
                           "clue_span": [doc["body_start"] + clue_span[0], doc["body_start"] + clue_span[1]],
                           "boundary_evidence": form, "clue_match": "all_normalized_words_in_order",
                           "semantic_status": "unverified; check requested type, relation, and answer form"})
    return fields


def run(ctx, inputs):
    question, context = inputs.get("question"), inputs.get("context")
    query, top_k = inputs.get("query", question), inputs.get("top_k", 4)
    if not isinstance(question, str) or not isinstance(context, str) or not isinstance(query, str):
        return {"status": "needs_input", "outputs": {}, "error": "question, context and query must be strings"}
    if isinstance(top_k, bool) or not isinstance(top_k, int) or not 1 <= top_k <= 6:
        return {"status": "needs_input", "outputs": {}, "error": "top_k must be an integer from 1 to 6"}
    documents, terms = _documents(context), _tokens(query)
    doc_terms = [_tokens(context[doc["start"]:doc["end"]]) for doc in documents]
    weights = {term: math.log(1 + (len(documents) + 1) / (1 + sum(term in group for group in doc_terms))) for term in terms}
    candidates = []
    for doc in documents:
        title = context[doc["title_start"]:doc["title_end"]]
        title_hits = terms & _tokens(title)
        body_start, end = doc["body_start"], doc["end"]
        starts = list(range(body_start, max(body_start + 1, end), 320))
        for start in starts:
            stop = min(end, start + 560)
            quote = context[start:stop]
            hits = terms & _tokens(quote)
            score = sum(weights[term] for term in hits) + 0.35 * sum(weights[term] for term in title_hits)
            candidates.append({"doc_id": doc["doc_id"], "span": [start, stop], "quote": quote,
                               "title": title, "title_span": [doc["title_start"], doc["title_end"]],
                               "matched_terms": sorted(hits | title_hits), "lexical_score": round(score, 6)})
    candidates.sort(key=lambda item: (-item["lexical_score"], item["doc_id"], item["span"][0]))
    windows, seen, per_doc = [], set(), {}
    for candidate in candidates:
        key = " ".join(candidate["quote"].casefold().split())
        if not key or key in seen or per_doc.get(candidate["doc_id"], 0) >= 2:
            continue
        seen.add(key)
        per_doc[candidate["doc_id"]] = per_doc.get(candidate["doc_id"], 0) + 1
        windows.append(candidate)
        if len(windows) >= top_k:
            break
    fields = _explicit_fields(context, question, documents)
    report = {"query": query, "windows": windows, "explicit_qa_fields": fields[:6],
              "omitted_qa_fields": max(0, len(fields) - 6), "source_document_count": len(documents),
              "offset_unit": "unicode_character_end_exclusive", "searched_source": "only_supplied_context",
              "meaning": "Lexical navigation and explicit field boundaries, not semantic proof, gold prediction, or a calibrated confidence score."}
    return {"status": "ok", "outputs": {"evidence_windows": report}}

"""Check exact source quotes and visible textual constraints without semantic grading."""
import re

_NUMBERS = {name: value for value, name in enumerate("zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty".split())}
_NUMBER = r"(?:[1-9][0-9]?|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty)"


def _documents(text):
    starts = [match.start() for match in re.finditer(r"\[DOC\]", text)]
    if not starts:
        starts = [0]
    elif text[:starts[0]].strip():
        starts.insert(0, 0)
    return [(start, starts[i + 1] if i + 1 < len(starts) else len(text)) for i, start in enumerate(starts)]


def _occurrences(text, value, documents):
    if not value:
        return []
    result = []
    for match in re.finditer(re.escape(value), text):
        number = next((i for i, (start, end) in enumerate(documents) if start <= match.start() and match.end() <= end), None)
        result.append({"span": [match.start(), match.end()], "doc_id": number, "within_single_doc": number is not None})
        if len(result) >= 12:
            break
    return result


def run(ctx, inputs):
    question, context, answer = inputs.get("question"), inputs.get("context"), inputs.get("answer")
    quotes = inputs.get("quotes", [])
    if not all(isinstance(value, str) for value in (question, context, answer)) or not answer.strip():
        return {"status": "needs_input", "outputs": {}, "error": "question/context strings and a nonempty answer are required"}
    if not isinstance(quotes, list) or len(quotes) > 8 or any(not isinstance(quote, str) or not quote or len(quote) > 1200 for quote in quotes):
        return {"status": "needs_input", "outputs": {}, "error": "quotes must contain at most 8 nonempty strings of at most 1200 characters"}
    documents, quote_checks, flags = _documents(context), [], []
    for quote in quotes:
        matches = _occurrences(context, quote, documents)
        status = "exact_single_doc" if any(item["within_single_doc"] for item in matches) else "cross_document" if matches else "not_found"
        quote_checks.append({"quote": quote, "status": status, "occurrences": matches})
        if status != "exact_single_doc":
            flags.append({"kind": "quote_" + status, "quote_index": len(quote_checks) - 1})
    constraints = []
    for unit in ("letter", "word"):
        pattern = re.compile(r"\b(?P<n>" + _NUMBER + r")[ -]+" + unit + r"(?:ed)?\s+(?:word|name|term|answer|phrase)\b", re.I)
        for match in pattern.finditer(question):
            raw = match.group("n").lower()
            expected = int(raw) if raw.isdigit() else _NUMBERS[raw]
            observed = sum(char.isalpha() for char in answer) if unit == "letter" else len(re.findall(r"[^\W_]+(?:['’-][^\W_]+)*", answer))
            constraints.append({"clue_span": [match.start(), match.end()], "clue_text": match.group(),
                                "kind": unit + "_count", "expected": expected, "observed": observed,
                                "literal_match": expected == observed, "scope": "unverified_may_describe_an_anchor"})
            if expected != observed:
                flags.append({"kind": "possible_" + unit + "_count_mismatch", "constraint_index": len(constraints) - 1})
    occurrences = _occurrences(context, answer, documents)
    report = {"answer": answer, "answer_exact_occurrences": occurrences, "quote_checks": quote_checks,
              "visible_length_constraints": constraints, "flags": flags,
              "semantic_status": "not_checked", "answer_presence_is_required": False,
              "offset_unit": "unicode_character_end_exclusive",
              "meaning": "Reconsider a specific flagged claim only. Literal presence does not prove the answer; absence can reflect a valid alias. Constraint scope still needs semantic judgment."}
    return {"status": "ok", "outputs": {"constraint_check": report}}

"""Pure answer-surface normalization; no corpus, task IDs, facts or gold lookup."""
import html
import re
import unicodedata

ONES = dict(zip('zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen'.split(), range(20)))
TENS = dict(zip('twenty thirty forty fifty sixty seventy eighty ninety'.split(), range(20, 100, 10)))


def small_number(text):
    parts = text.lower().replace('-', ' ').split()
    if len(parts) == 1:
        return ONES.get(parts[0], TENS.get(parts[0]))
    if len(parts) == 2 and parts[0] in TENS and parts[1] in ONES and 0 < ONES[parts[1]] < 10:
        return TENS[parts[0]] + ONES[parts[1]]
    return None


def normalize(answer, question):
    changes = []
    body = answer.strip()
    match = re.fullmatch(r'<answer>(.*?)</answer>', body, re.S)
    if match:
        body = match.group(1).strip()
    if not body or re.search(r'</?answer\b', body, re.I):
        raise ValueError('Exactly one nonempty answer is required')
    decoded = html.unescape(body)
    if decoded != body:
        changes.append('html_entities')
        body = decoded
    # Typography only: preserve accent letters and all lexical words.
    plain = body.translate(str.maketrans({'‘': "'", '’': "'", '“': '"', '”': '"', '–': '-', '—': '-'}))
    if plain != body:
        changes.append('typographic_punctuation')
        body = plain
    ascii_name = unicodedata.normalize('NFC', ''.join(ch for ch in unicodedata.normalize('NFD', body) if not unicodedata.combining(ch)))
    if ascii_name != body:
        changes.append('latin_diacritics')
        body = ascii_name
    compact = re.sub(r'\b((?:[A-Z]\.\s+)+)(?=[A-Z]\.)', lambda m: re.sub(r'\s+', '', m.group(0)), body)
    if compact != body:
        changes.append('compact_initials')
        body = compact
    quantity = bool(re.search(r'\b(?:how many|how much|this many|this number|number of|this age|what age|how old|what percent|what percentage|this percent|this percentage)\b', question, re.I))
    if quantity:
        numeric = small_number(body)
        if numeric is not None:
            body = str(numeric)
            changes.append('small_quantity_digits')
        suffix = None
        if re.search(r'\b(?:age|old)\b', question, re.I):
            suffix = r'years? old'
        elif re.search(r'\b(?:percent|percentage)\b', question, re.I):
            suffix = r'(?:percent|per cent|percentage points|%)'
        if suffix:
            match = re.fullmatch(r'([+-]?\d+(?:\.\d+)?)\s*' + suffix, body, re.I)
            if match:
                body = match.group(1)
                changes.append('unit_already_in_question')
    if not body or re.search(r'</?answer\b', body, re.I):
        raise ValueError('Decoded nested/empty answer is not allowed')
    return body, changes


def run(ctx, inputs):
    answer, question = inputs.get('answer'), inputs.get('question')
    if not isinstance(answer, str) or not isinstance(question, str):
        return {'status': 'needs_input', 'outputs': {}, 'error': 'answer and question strings required'}
    try:
        value, changes = normalize(answer, question)
    except ValueError as error:
        return {'status': 'needs_input', 'outputs': {}, 'error': str(error)}
    return {'status': 'ok', 'outputs': {'answer': '<answer>' + value + '</answer>',
        'surface_audit': {'raw_answer': answer, 'normalized_answer': value, 'changes': changes,
                          'semantic_validation': False}}}
